```yaml
name: Dependabot Auto-Merge

on:
  pull_request:
    types: [opened, synchronize, reopened]
  workflow_run:
    workflows: ["Only CI/CT"]
    types: [completed]

permissions:
  contents: write
  pull-requests: write
  checks: read

jobs:
  dependabot-auto-merge:
    runs-on: ubuntu-latest
    if: ${{ github.event.pull_request.user.login == 'dependabot[bot]' }}
    steps:
      - name: Wait for workflow run to complete
        if: github.event_name == 'workflow_run'
        run: |
          sleep 5

      - name: Fetch Dependabot metadata
        id: dependabot-metadata
        uses: dependabot/fetch-metadata@v2
        if: github.event_name == 'pull_request'

      - name: Check if PR is from Dependabot
        id: check-dependabot
        run: |
          if [[ "${{ github.event.pull_request.user.login }}" != "dependabot[bot]" ]]; then
            echo "Not a Dependabot PR, exiting..."
            exit 1
          fi

      - name: Check workflow run status
        id: check-workflow-run
        if: github.event_name == 'workflow_run'
        run: |
          if [[ "${{ github.event.workflow_run.conclusion }}" != "success" ]]; then
            echo "Workflow did not succeed, skipping merge."
            exit 1
          fi

      - name: Get PR status
        id: get-pr-status
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = context.issue.number;
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            const { data: pr } = await github.rest.pulls.get({
              owner: owner,
              repo: repo,
              pull_number: prNumber
            });

            const { data: checks } = await github.rest.checks.listForRef({
              owner: owner,
              repo: repo,
              ref: pr.head.sha
            });

            const hasValidation = checks.check_runs.length > 0;
            const hasFailedOrCancelled = checks.check_runs.some(run => 
              run.status === 'completed' && (run.conclusion === 'failure' || run.conclusion === 'cancelled')
            );

            if (!hasValidation) {
              console.log("No validation checks found, skipping merge.");
              return;
            }

            if (hasFailedOrCancelled) {
              console.log("Failed or cancelled checks detected, skipping merge.");
              return;
            }

            // Check if already approved
            const { data: reviews } = await github.rest.pulls.listReviews({
              owner: owner,
              repo: repo,
              pull_number: prNumber
            });

            const hasApproval = reviews.some(review => 
              review.state === 'APPROVED' && review.user.login === 'dependabot[bot]'
            );

            core.setOutput('has_validation', hasValidation);
            core.setOutput('has_failed_or_cancelled', hasFailedOrCancelled);
            core.setOutput('has_approval', hasApproval);

      - name: Approve PR
        if: steps.get-pr-status.outputs.has_validation == 'true' && steps.get-pr-status.outputs.has_failed_or_cancelled == 'false' && steps.get-pr-status.outputs.has_approval == 'false'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = context.issue.number;
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            await github.rest.pulls.createReview({
              owner: owner,
              repo: repo,
              pull_number: prNumber,
              event: 'APPROVE',
              body: 'Automated approval based on successful CI checks.'
            });

      - name: Enable auto-merge
        if: steps.get-pr-status.outputs.has_validation == 'true' && steps.get-pr-status.outputs.has_failed_or_cancelled == 'false'
        uses: peter-evans/enable-pull-request-automerge@v3
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          pull-request-number: ${{ github.event.pull_request.number }}
          merge-method: "squash"
